#!/bin/bash
# gen_plans.sh: Linux's DML (dml314_run) for the 8500G's HDMI monitor modes, as C tables for testl:
# src/amd/phx_dml314_plans.h. Timings: the MSI G255F's EDID modes 0 (60 Hz) and 1 (144 Hz) as Test K decoded them
# (hardware/dumps/b650m_8500g/testk.txt). Each mode twice: DCHUB refclk 24 MHz and 12 MHz (REFDIV 2), testl picks the
# one DCHUBBUB_GLOBAL_TIMER_CNTL says.
set -e
cd "$(dirname "$0")/../.."
[ -x build/dml/dml314_run ] || bash tools/dml/build.sh
OUT=src/amd/phx_dml314_plans.h
TMP=$(mktemp)
cat > "$TMP" <<'H'
// phx_dml314_plans.h: GENERATED by tools/dml/gen_plans.sh (Linux v6.17 DML for DCN 3.1.4, tools/dml/dml314_run).
// Do not edit. The values Linux would program for one HDMI pipe at the MSI G255F's EDID modes.
#pragma once
struct PhxDmlVal { const char *name; unsigned v; };

H
M60="148500 1920 88 44 2200 1080 4 5 1125"
M144="335770 1920 48 32 2080 1080 4 5 1121"
./build/dml/dml314_run $M60 --emit "$TMP" kDml60 >/dev/null
./build/dml/dml314_run $M60 --refdiv2 --emit "$TMP" kDml60Refdiv2 >/dev/null
./build/dml/dml314_run $M144 --emit "$TMP" kDml144 >/dev/null
./build/dml/dml314_run $M144 --refdiv2 --emit "$TMP" kDml144Refdiv2 >/dev/null
cat >> "$TMP" <<'H'
static inline bool phxDmlGet(const PhxDmlVal *t, const char *name, unsigned *v) {
    for (; t->name; t++) {
        const char *a = t->name, *b = name;
        while (*a && *a == *b) { a++; b++; }
        if (!*a && !*b) { *v = t->v; return true; }
    }
    return false;
}
H
mv "$TMP" "$OUT"
echo "wrote $OUT"
